import {petForm} from './pet-forms.js?v=21';
import {visualAssets,drawCell} from './engine/visual-assets.js?v=21';
import {COMPANIONS,magiculaTier} from './companions.js?v=21';
export function drawCompanion(g,p,kind,t,moving=false){const id=p.companions?.[kind],d=COMPANIONS.find(v=>v.id===id);if(!d||!p.companions.owned[id]||!visualAssets.companions)return;g.save();const bob=Math.sin(t*(moving?8:2))*1.5,rank=p.companions.owned[id].rank;if(kind==='pet'){g.translate(0,bob);if(id==='slime')g.scale(1+Math.sin(t*3)*.05,1-Math.sin(t*3)*.04);const form=petForm(id,rank);g.beginPath();g.ellipse(0,-15,25,27,0,0,Math.PI*2);g.clip();g.imageSmoothingEnabled=true;if(id==='drake'&&rank>=300&&visualAssets.cosmic)drawCell(g,visualAssets.cosmic,3,2,5,-24,-42,48,48);else if(form&&visualAssets.petForms)drawCell(g,visualAssets.petForms,6,3,form.cell,-20,-36,40,40);else drawCell(g,visualAssets.companions,3,2,d.cell,-16,-30,32,32);}else{g.translate(0,moving?Math.abs(Math.sin(t*9))*-2:0);drawCell(g,visualAssets.companions,3,2,d.cell,-52,-75,104,83);}if(rank>=20){g.globalCompositeOperation='lighter';g.fillStyle='#92eaff';for(let n=0;n<Math.min(8,rank/15);n++){const a=t*.5+n*2.4;g.globalAlpha=.5;g.fillRect(Math.cos(a)*(kind==='pet'?15:40),-18+Math.sin(a)*8,1,2);}}g.restore();}
export function drawMagicula(g,rank,t){if(!rank||!visualAssets.sigils)return;const tier=magiculaTier(rank),size=12+tier*2;g.save();g.translate(25+Math.sin(t*.3)*2,-85+Math.sin(t*1.8)*2);g.rotate(t*.018);g.globalAlpha=.9;drawCell(g,visualAssets.sigils,4,2,tier,-size/2,-size/2,size,size);g.globalCompositeOperation='lighter';g.strokeStyle=['#eee','#55ff55','#cd59ff','#ffb635','#00ffff','#f7deff'][tier];for(let n=0;n<Math.min(3,1+Math.floor(rank/40));n++){g.save();g.rotate(t*.12+n);g.beginPath();g.ellipse(0,0,size*.65+n*3,size*.25+n,0,0,Math.PI*2);g.globalAlpha=.35;g.stroke();g.restore();}g.restore();}
